hooks.command:
py=$(command -v py || command -v python3 || command -v python) || exit 0
"$py" -c 'import ast, json, sys
p = json.load(sys.stdin).get("tool_input", {}).get("file_path", "")
try:
    if p.endswith(".py"):
        ast.parse(open(p, encoding="utf-8").read(), p)
    elif p.endswith(".json"):
        json.load(open(p, encoding="utf-8"))
except (SyntaxError, ValueError) as e:
    print(f"Arquivo inválido depois da edição: {p}: {e}", file=sys.stderr)
    sys.exit(2)'
